// Draft-07 keyword validators, mirroring jsonschema's _validators.py /
// _legacy_keywords.py behavior (error counts and instance paths).
//
// Each validator is a generator receiving:
//   ctx      - { descend(instance, subschema, path), isValid(instance, subschema) }
//   value    - the keyword's value in the schema
//   instance - the instance being validated
//   schema   - the schema object containing the keyword
//   path     - the instance path of the current location
// and yields error objects created by makeError.

import { isPlainObject, hasKey, isType, pyEq, strLen } from "./pytypes.mjs";
import { makeError } from "./errors.mjs";

function* type_(ctx, value, instance, schema, path) {
  const types = Array.isArray(value) ? value : [value];
  if (!types.some((t) => isType(instance, t))) {
    yield makeError("type", path, `${JSON.stringify(instance)} is not of type ${JSON.stringify(value)}`);
  }
}

function* enum_(ctx, value, instance, schema, path) {
  if (!Array.isArray(value) || !value.some((each) => pyEq(instance, each))) {
    yield makeError("enum", path, `${JSON.stringify(instance)} is not one of ${JSON.stringify(value)}`);
  }
}

function* const_(ctx, value, instance, schema, path) {
  if (!pyEq(instance, value)) {
    yield makeError("const", path, `${JSON.stringify(value)} was expected`);
  }
}

function* multipleOf(ctx, value, instance, schema, path) {
  if (typeof instance !== "number") return;
  const quotient = instance / value;
  if (!Number.isInteger(quotient)) {
    yield makeError("multipleOf", path, `${instance} is not a multiple of ${value}`);
  }
}

function* maximum(ctx, value, instance, schema, path) {
  if (typeof instance !== "number") return;
  if (instance > value) {
    yield makeError("maximum", path, `${instance} is greater than the maximum of ${value}`);
  }
}

function* exclusiveMaximum(ctx, value, instance, schema, path) {
  if (typeof instance !== "number") return;
  if (instance >= value) {
    yield makeError("exclusiveMaximum", path, `${instance} is greater than or equal to the maximum of ${value}`);
  }
}

function* minimum(ctx, value, instance, schema, path) {
  if (typeof instance !== "number") return;
  if (instance < value) {
    yield makeError("minimum", path, `${instance} is less than the minimum of ${value}`);
  }
}

function* exclusiveMinimum(ctx, value, instance, schema, path) {
  if (typeof instance !== "number") return;
  if (instance <= value) {
    yield makeError("exclusiveMinimum", path, `${instance} is less than or equal to the minimum of ${value}`);
  }
}

function* maxLength(ctx, value, instance, schema, path) {
  if (typeof instance !== "string") return;
  if (strLen(instance) > value) {
    yield makeError("maxLength", path, `${JSON.stringify(instance)} is too long`);
  }
}

function* minLength(ctx, value, instance, schema, path) {
  if (typeof instance !== "string") return;
  if (strLen(instance) < value) {
    yield makeError("minLength", path, `${JSON.stringify(instance)} is too short`);
  }
}

function* pattern(ctx, value, instance, schema, path) {
  if (typeof instance !== "string") return;
  const re = new RegExp(value);
  if (!re.test(instance)) {
    yield makeError("pattern", path, `${JSON.stringify(instance)} does not match ${JSON.stringify(value)}`);
  }
}

function* items(ctx, value, instance, schema, path) {
  if (!Array.isArray(instance)) return;
  if (Array.isArray(value)) {
    const n = Math.min(instance.length, value.length);
    for (let i = 0; i < n; i++) {
      yield* ctx.descend(instance[i], value[i], path.concat(i));
    }
  } else {
    // Object or boolean schema applies to every element.
    for (let i = 0; i < instance.length; i++) {
      yield* ctx.descend(instance[i], value, path.concat(i));
    }
  }
