  if (!Array.isArray(instance)) return;
  const itemsValue = hasKey(schema, "items") ? schema.items : {};
  if (!Array.isArray(itemsValue)) {
    // jsonschema proceeds to len(items) here and crashes for booleans.
    if (typeof itemsValue === "boolean") {
      throw new TypeError(`object of type 'bool' has no len()`);
    }
    return;
