function* maxItems(ctx, value, instance, schema, path) {
  if (!Array.isArray(instance)) return;
  if (instance.length > value) {
    yield makeError("maxItems", path, `${JSON.stringify(instance)} is too long`);
  }
}

function* minItems(ctx, value, instance, schema, path) {
  if (!Array.isArray(instance)) return;
  if (instance.length < value) {
    yield makeError("minItems", path, `${JSON.stringify(instance)} is too short`);
  }
}

function* uniqueItems(ctx, value, instance, schema, path) {
  if (!value || !Array.isArray(instance)) return;
  for (let i = 0; i < instance.length; i++) {
    for (let j = i + 1; j < instance.length; j++) {
      if (pyEq(instance[i], instance[j])) {
        yield makeError("uniqueItems", path, `${JSON.stringify(instance)} has non-unique elements`);
        return;
      }
    }
  }
}

function* contains(ctx, value, instance, schema, path) {
  if (!Array.isArray(instance)) return;
  if (!instance.some((element) => ctx.isValid(element, value))) {
    yield makeError("contains", path, "None of the items are valid under the given schema");
  }
}

function* maxProperties(ctx, value, instance, schema, path) {
  if (!isPlainObject(instance)) return;
  if (Object.keys(instance).length > value) {
    yield makeError("maxProperties", path, `${JSON.stringify(instance)} has too many properties`);
  }
}

function* minProperties(ctx, value, instance, schema, path) {
  if (!isPlainObject(instance)) return;
  if (Object.keys(instance).length < value) {
    yield makeError("minProperties", path, `${JSON.stringify(instance)} does not have enough properties`);
  }
}

function* required(ctx, value, instance, schema, path) {
  if (!isPlainObject(instance)) return;
  if (!Array.isArray(value)) return; // invalid schema; check_schema rejects it
  for (const property of value) {
    if (typeof property !== "string" || !hasKey(instance, property)) {
      yield makeError("required", path, `${JSON.stringify(property)} is a required property`);
    }
  }
}

function* dependencies(ctx, value, instance, schema, path) {
  if (!isPlainObject(instance)) return;
  if (!isPlainObject(value)) return;
  for (const [property, dependency] of Object.entries(value)) {
    if (!hasKey(instance, property)) continue;
    if (Array.isArray(dependency)) {
      for (const each of dependency) {
        if (typeof each !== "string" || !hasKey(instance, each)) {
          yield makeError("dependencies", path, `${JSON.stringify(each)} is a dependency of ${JSON.stringify(property)}`);
        }
      }
    } else {
      // Anything else is treated as a schema (a non-object/non-boolean
      // value crashes inside descend, exactly like jsonschema).
      yield* ctx.descend(instance, dependency, path);
    }
  }
}

function* properties(ctx, value, instance, schema, path) {
  if (!isPlainObject(instance)) return;
  if (!isPlainObject(value)) return;
  for (const key of Object.keys(value)) {
    if (hasKey(instance, key)) {
      yield* ctx.descend(instance[key], value[key], path.concat(key));
    }
  }
}

function* patternProperties(ctx, value, instance, schema, path) {
  if (!isPlainObject(instance)) return;
  if (!isPlainObject(value)) return;
  for (const [pattern, subschema] of Object.entries(value)) {
    const re = new RegExp(pattern);
    for (const key of Object.keys(instance)) {
      if (re.test(key)) {
        yield* ctx.descend(instance[key], subschema, path.concat(key));
      }
    }
  }
}

function* additionalProperties(ctx, value, instance, schema, path) {
  if (!isPlainObject(instance)) return;
  const declared = isPlainObject(schema.properties) ? Object.keys(schema.properties) : [];
  const patterns = isPlainObject(schema.patternProperties)
    ? Object.keys(schema.patternProperties).map((p) => new RegExp(p))
    : [];
  const extras = Object.keys(instance).filter(
    (key) => !declared.includes(key) && !patterns.some((re) => re.test(key)),
  );
  if (isPlainObject(value)) {
    for (const extra of extras) {
      yield* ctx.descend(instance[extra], value, path.concat(extra));
    }
  } else if (!value && extras.length > 0) {
    yield makeError("additionalProperties", path, "Additional properties are not allowed");
  }
}

function* propertyNames(ctx, value, instance, schema, path) {
  if (!isPlainObject(instance)) return;
  // Note: jsonschema does not extend the instance path here.
  for (const property of Object.keys(instance)) {
    yield* ctx.descend(property, value, path);
