  process.stderr.write(`${usageLine(prog)}\n`);
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function printHelp(prog) {
  process.stdout.write(`${usageLine(prog)}\n`);
  process.stdout.write(`\n`);
  process.stdout.write(`options:\n`);
  process.stdout.write(`  -h, --help  show this help message and exit\n`);
  process.stdout.write(`  --a A       instance (JSON string)\n`);
  process.stdout.write(`  --b B       schema (JSON string)\n`);
  process.exit(0);
