  return value === null ? "None" : String(value);
}

function main() {
  const prog = basename(process.argv[1] || "test18.mjs");
  const args = parseArgs(process.argv.slice(2), prog);

  // json.loads failures abort the Python program with a traceback (exit 1).
  const instance = pyJsonParse(args.a);
