  // Validate schema multiple times (raises SchemaError on invalid schemas)
  const schemaCheck1 = validator.checkSchema(schema);
  const schemaCheck2 = validator.checkSchema(schema);

  // Create error trees for each pass
  const tree1 = new ErrorTree(firstPass);
  const tree2 = new ErrorTree(secondPass);

